using System.IO;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using MiniC.Models;
namespace MiniC.Widgets;
public enum WidgetKind { Note, Tasks, Schedule, Calendar, Weather, Planner }
public sealed class WidgetState { public string Id {get;set;}=Guid.NewGuid().ToString("N"); public WidgetKind Kind{get;set;} public string Title{get;set;}=""; public double X{get;set;}=80; public double Y{get;set;}=120; public double Width{get;set;}=340; public double Height{get;set;}=380; public bool Collapsed{get;set;} public string Material{get;set;}="Crystal"; public string Theme{get;set;}="Graphite"; public double Opacity{get;set;}=0.62; public MaterialPreferences Appearance{get;set;}=new(); public string Body{get;set;}=""; public string City{get;set;}=""; public string ViewMode{get;set;}=""; public DateTimeOffset? ReminderUtc{get;set;} public DateTimeOffset? NotifiedUtc{get;set;} }
public sealed class WidgetEntry { public string Id{get;set;}=Guid.NewGuid().ToString("N"); public string WidgetId{get;set;}=""; public string Title{get;set;}=""; public string Body{get;set;}=""; public DateTimeOffset? DueUtc{get;set;} public DateTimeOffset? ReminderUtc{get;set;} public DateTimeOffset? NotifiedUtc{get;set;} public bool Completed{get;set;} public string EntryKind{get;set;}="Task"; }
public sealed record DatedWidgetEntry(WidgetEntry Entry, WidgetKind Kind);
public sealed record WidgetAttachment(string Id,string WidgetId,string? EntryId,string Name,string StoredName);
public sealed record WidgetReminder(string Id,string WidgetId,string Title,bool IsEntry);
public sealed class WidgetStore {
 readonly string dbPath, filesPath; public WidgetStore():this(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MiniC")){} internal WidgetStore(string root){Directory.CreateDirectory(root);dbPath=Path.Combine(root,"widgets.db");filesPath=Path.Combine(root,"WidgetAttachments");using var db=Open(); Exec(db,"PRAGMA journal_mode=WAL;"); Exec(db,"CREATE TABLE IF NOT EXISTS widgets (id TEXT PRIMARY KEY,kind INTEGER NOT NULL,title TEXT NOT NULL,x REAL NOT NULL,y REAL NOT NULL,width REAL NOT NULL,height REAL NOT NULL,collapsed INTEGER NOT NULL,material TEXT NOT NULL,theme TEXT NOT NULL,opacity REAL NOT NULL,appearance_json TEXT NOT NULL DEFAULT '{}',body TEXT NOT NULL,city TEXT NOT NULL,view_mode TEXT NOT NULL DEFAULT '',reminder_utc TEXT,notified_utc TEXT); CREATE TABLE IF NOT EXISTS entries (id TEXT PRIMARY KEY,widget_id TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,due_utc TEXT,reminder_utc TEXT,notified_utc TEXT,completed INTEGER NOT NULL,entry_kind TEXT NOT NULL DEFAULT 'Task'); CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY,widget_id TEXT NOT NULL,entry_id TEXT,name TEXT NOT NULL,stored_name TEXT NOT NULL);"); Ensure(db,"widgets","view_mode","TEXT NOT NULL DEFAULT ''"); Ensure(db,"widgets","appearance_json","TEXT NOT NULL DEFAULT '{}'"); Ensure(db,"entries","entry_kind","TEXT NOT NULL DEFAULT 'Task'");}
 SqliteConnection Open(){var d=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=dbPath,Pooling=false}.ToString());d.Open();Exec(d,"PRAGMA foreign_keys=ON;");return d;} static void Exec(SqliteConnection d,string s){using var c=d.CreateCommand();c.CommandText=s;c.ExecuteNonQuery();} static void Ensure(SqliteConnection d,string t,string n,string def){using var c=d.CreateCommand();c.CommandText=$"PRAGMA table_info({t})";using var r=c.ExecuteReader();while(r.Read())if(r.GetString(1).Equals(n,StringComparison.OrdinalIgnoreCase))return;r.Close();Exec(d,$"ALTER TABLE {t} ADD COLUMN {n} {def}");}
 static string? Stamp(DateTimeOffset? v)=>v?.ToUniversalTime().ToString("O"); static DateTimeOffset? Date(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:DateTimeOffset.Parse(r.GetString(i)); static MaterialPreferences Appearance(string j,double o){try{return (JsonSerializer.Deserialize<MaterialPreferences>(j)??new()).Normalize();}catch{return new MaterialPreferences{FrostedOpacity=o,CrystalOpacity=o};}}
 public List<WidgetState> Widgets(){using var d=Open();using var c=d.CreateCommand();c.CommandText="SELECT id,kind,title,x,y,width,height,collapsed,material,theme,opacity,appearance_json,body,city,view_mode,reminder_utc,notified_utc FROM widgets ORDER BY rowid";using var r=c.ExecuteReader();var a=new List<WidgetState>();while(r.Read())a.Add(new WidgetState{Id=r.GetString(0),Kind=(WidgetKind)r.GetInt32(1),Title=r.GetString(2),X=r.GetDouble(3),Y=r.GetDouble(4),Width=r.GetDouble(5),Height=r.GetDouble(6),Collapsed=r.GetInt32(7)!=0,Material=r.GetString(8),Theme=r.GetString(9),Opacity=r.GetDouble(10),Appearance=Appearance(r.GetString(11),r.GetDouble(10)),Body=r.GetString(12),City=r.GetString(13),ViewMode=r.GetString(14),ReminderUtc=Date(r,15),NotifiedUtc=Date(r,16)});return a;}
 public void Save(WidgetState s){using var d=Open();using var c=d.CreateCommand();c.CommandText="INSERT INTO widgets (id,kind,title,x,y,width,height,collapsed,material,theme,opacity,appearance_json,body,city,view_mode,reminder_utc,notified_utc) VALUES ($id,$kind,$title,$x,$y,$w,$h,$col,$mat,$theme,$op,$app,$body,$city,$view,$rem,$not) ON CONFLICT(id) DO UPDATE SET title=excluded.title,x=excluded.x,y=excluded.y,width=excluded.width,height=excluded.height,collapsed=excluded.collapsed,material=excluded.material,theme=excluded.theme,opacity=excluded.opacity,appearance_json=excluded.appearance_json,body=excluded.body,city=excluded.city,view_mode=excluded.view_mode,reminder_utc=excluded.reminder_utc,notified_utc=excluded.notified_utc"; c.Parameters.AddWithValue("$id",s.Id);c.Parameters.AddWithValue("$kind",(int)s.Kind);c.Parameters.AddWithValue("$title",s.Title);c.Parameters.AddWithValue("$x",s.X);c.Parameters.AddWithValue("$y",s.Y);c.Parameters.AddWithValue("$w",s.Width);c.Parameters.AddWithValue("$h",s.Height);c.Parameters.AddWithValue("$col",s.Collapsed?1:0);c.Parameters.AddWithValue("$mat",s.Material);c.Parameters.AddWithValue("$theme",s.Theme);c.Parameters.AddWithValue("$op",s.Opacity);c.Parameters.AddWithValue("$app",JsonSerializer.Serialize(s.Appearance.Normalize()));c.Parameters.AddWithValue("$body",s.Body);c.Parameters.AddWithValue("$city",s.City);c.Parameters.AddWithValue("$view",s.ViewMode);c.Parameters.AddWithValue("$rem",(object?)Stamp(s.ReminderUtc)??DBNull.Value);c.Parameters.AddWithValue("$not",(object?)Stamp(s.NotifiedUtc)??DBNull.Value);c.ExecuteNonQuery();}
 public List<WidgetEntry> Entries(string? id=null){using var d=Open();using var c=d.CreateCommand();c.CommandText="SELECT id,widget_id,title,body,due_utc,reminder_utc,notified_utc,completed,entry_kind FROM entries"+(id==null?"":" WHERE widget_id=$id");if(id!=null)c.Parameters.AddWithValue("$id",id);using var r=c.ExecuteReader();var a=new List<WidgetEntry>();while(r.Read())a.Add(new WidgetEntry{Id=r.GetString(0),WidgetId=r.GetString(1),Title=r.GetString(2),Body=r.GetString(3),DueUtc=Date(r,4),ReminderUtc=Date(r,5),NotifiedUtc=Date(r,6),Completed=r.GetInt32(7)!=0,EntryKind=r.GetString(8)});return a;}
 public List<DatedWidgetEntry> DatedEntries(){using var d=Open();using var c=d.CreateCommand();c.CommandText="SELECT e.id,e.widget_id,e.title,e.body,e.due_utc,e.reminder_utc,e.notified_utc,e.completed,e.entry_kind,w.kind FROM entries e JOIN widgets w ON w.id=e.widget_id WHERE e.due_utc IS NOT NULL AND w.kind IN ($tasks,$schedule,$planner)";c.Parameters.AddWithValue("$tasks",(int)WidgetKind.Tasks);c.Parameters.AddWithValue("$schedule",(int)WidgetKind.Schedule);c.Parameters.AddWithValue("$planner",(int)WidgetKind.Planner);using var r=c.ExecuteReader();var a=new List<DatedWidgetEntry>();while(r.Read()){var entryKind=r.GetString(8);var widgetKind=(WidgetKind)r.GetInt32(9);var isSchedule=widgetKind==WidgetKind.Schedule||entryKind.Equals("Schedule",StringComparison.OrdinalIgnoreCase);a.Add(new DatedWidgetEntry(new WidgetEntry{Id=r.GetString(0),WidgetId=r.GetString(1),Title=r.GetString(2),Body=r.GetString(3),DueUtc=Date(r,4),ReminderUtc=Date(r,5),NotifiedUtc=Date(r,6),Completed=r.GetInt32(7)!=0,EntryKind=isSchedule?"Schedule":"Task"},isSchedule?WidgetKind.Schedule:WidgetKind.Tasks));}return a;}
 public void Save(WidgetEntry e){using var d=Open();using var c=d.CreateCommand();c.CommandText="INSERT INTO entries (id,widget_id,title,body,due_utc,reminder_utc,notified_utc,completed,entry_kind) VALUES($id,$wid,$title,$body,$due,$rem,$not,$done,$kind) ON CONFLICT(id) DO UPDATE SET title=excluded.title,body=excluded.body,due_utc=excluded.due_utc,reminder_utc=excluded.reminder_utc,notified_utc=excluded.notified_utc,completed=excluded.completed,entry_kind=excluded.entry_kind";c.Parameters.AddWithValue("$id",e.Id);c.Parameters.AddWithValue("$wid",e.WidgetId);c.Parameters.AddWithValue("$title",e.Title);c.Parameters.AddWithValue("$body",e.Body);c.Parameters.AddWithValue("$due",(object?)Stamp(e.DueUtc)??DBNull.Value);c.Parameters.AddWithValue("$rem",(object?)Stamp(e.ReminderUtc)??DBNull.Value);c.Parameters.AddWithValue("$not",(object?)Stamp(e.NotifiedUtc)??DBNull.Value);c.Parameters.AddWithValue("$done",e.Completed?1:0);c.Parameters.AddWithValue("$kind",e.EntryKind.Equals("Schedule",StringComparison.OrdinalIgnoreCase)?"Schedule":"Task");c.ExecuteNonQuery();}
 public List<WidgetAttachment> Attachments(string id){using var d=Open();using var c=d.CreateCommand();c.CommandText="SELECT id,widget_id,entry_id,name,stored_name FROM attachments WHERE widget_id=$id";c.Parameters.AddWithValue("$id",id);using var r=c.ExecuteReader();var a=new List<WidgetAttachment>();while(r.Read())a.Add(new WidgetAttachment(r.GetString(0),r.GetString(1),r.IsDBNull(2)?null:r.GetString(2),r.GetString(3),r.GetString(4)));return a;}
 public string AttachmentPath(WidgetAttachment a)=>SafePath(a.WidgetId,a.StoredName); public WidgetAttachment Import(string wid,string? eid,string src){var dir=SafeAttachmentDirectory(wid);Directory.CreateDirectory(dir);var id=Guid.NewGuid().ToString("N");var name=Path.GetFileName(src);var stored=id+Path.GetExtension(name);File.Copy(src,SafePath(wid,stored));var a=new WidgetAttachment(id,wid,eid,name,stored);using var d=Open();using var c=d.CreateCommand();c.CommandText="INSERT INTO attachments VALUES($id,$wid,$eid,$name,$stored)";c.Parameters.AddWithValue("$id",id);c.Parameters.AddWithValue("$wid",wid);c.Parameters.AddWithValue("$eid",(object?)eid??DBNull.Value);c.Parameters.AddWithValue("$name",name);c.Parameters.AddWithValue("$stored",stored);c.ExecuteNonQuery();return a;}
 public List<WidgetReminder> ClaimDue(DateTimeOffset now){using var d=Open();var a=new List<WidgetReminder>();using(var c=d.CreateCommand()){c.CommandText="SELECT id,id,title,0 FROM widgets WHERE reminder_utc IS NOT NULL AND reminder_utc <= $now AND notified_utc IS NULL UNION ALL SELECT id,widget_id,title,1 FROM entries WHERE completed=0 AND reminder_utc IS NOT NULL AND reminder_utc <= $now AND notified_utc IS NULL";c.Parameters.AddWithValue("$now",now.ToUniversalTime().ToString("O"));using var r=c.ExecuteReader();while(r.Read())a.Add(new WidgetReminder(r.GetString(0),r.GetString(1),r.GetString(2),r.GetInt32(3)!=0));}foreach(var x in a){using var c=d.CreateCommand();c.CommandText=x.IsEntry?"UPDATE entries SET notified_utc=$now WHERE id=$id":"UPDATE widgets SET notified_utc=$now WHERE id=$id";c.Parameters.AddWithValue("$now",now.ToUniversalTime().ToString("O"));c.Parameters.AddWithValue("$id",x.Id);c.ExecuteNonQuery();}return a;}
 public void DeleteWidget(string id){var dir=SafeAttachmentDirectory(id);using var d=Open();using(var a=d.CreateCommand()){a.CommandText="DELETE FROM attachments WHERE widget_id=$id";a.Parameters.AddWithValue("$id",id);a.ExecuteNonQuery();}using(var e=d.CreateCommand()){e.CommandText="DELETE FROM entries WHERE widget_id=$id";e.Parameters.AddWithValue("$id",id);e.ExecuteNonQuery();}using(var c=d.CreateCommand()){c.CommandText="DELETE FROM widgets WHERE id=$id";c.Parameters.AddWithValue("$id",id);c.ExecuteNonQuery();}if(Directory.Exists(dir))Directory.Delete(dir,true);} public void DeleteEntry(string id){using var d=Open();var files=new List<string>();using(var q=d.CreateCommand()){q.CommandText="SELECT widget_id,stored_name FROM attachments WHERE entry_id=$id";q.Parameters.AddWithValue("$id",id);using var r=q.ExecuteReader();while(r.Read())files.Add(SafePath(r.GetString(0),r.GetString(1)));}using(var c=d.CreateCommand()){c.CommandText="DELETE FROM attachments WHERE entry_id=$id";c.Parameters.AddWithValue("$id",id);c.ExecuteNonQuery();}using(var c=d.CreateCommand()){c.CommandText="DELETE FROM entries WHERE id=$id";c.Parameters.AddWithValue("$id",id);c.ExecuteNonQuery();}foreach(var f in files)if(File.Exists(f))File.Delete(f);} public string SafePath(string id,string file){var dir=SafeAttachmentDirectory(id);if(!IsSafeComponent(file))throw new ArgumentException("Invalid attachment file name.",nameof(file));return Path.Combine(dir,file);} private string SafeAttachmentDirectory(string id){if(!IsSafeComponent(id))throw new ArgumentException("Invalid widget ID.",nameof(id));return Path.Combine(filesPath,id);} private static bool IsSafeComponent(string? value)=>!string.IsNullOrEmpty(value)&&value is not ("." or "..")&&!Path.IsPathRooted(value)&&value.IndexOfAny(['/', '\\', ':'])<0&&value.IndexOfAny(Path.GetInvalidFileNameChars())<0; public void DeleteAttachment(WidgetAttachment a){var p=AttachmentPath(a);using var d=Open();using var c=d.CreateCommand();c.CommandText="DELETE FROM attachments WHERE id=$id";c.Parameters.AddWithValue("$id",a.Id);c.ExecuteNonQuery();if(File.Exists(p))File.Delete(p);}
}






